def distinctPerWindow(nums, k):
    cnt = {}
    distinct = 0
    res = []
    for i, x in enumerate(nums):
        c = cnt.get(x, 0)
        if c == 0:
            distinct += 1
        cnt[x] = c + 1
        if i >= k:
            y = nums[i - k]
            cnt[y] -= 1
            if cnt[y] == 0:
                distinct -= 1
        if i >= k - 1:
            res.append(distinct)
    return res
